#requires -Version 5.1
$ErrorActionPreference = 'Stop'
Set-Location (Split-Path $PSScriptRoot -Parent)
if (-not (Get-Command flutter -ErrorAction SilentlyContinue)) {
    throw 'Flutter introuvable. Installer Flutter stable et ajouter flutter\bin au PATH.'
}
flutter --version
# Native runner scaffolds are intentionally generated by the Flutter SDK.
# No --overwrite : preserve hand-authored files, especially lib/ and pubspec.yaml.
flutter create --project-name lifequest_mobile --platforms android,ios .
if ($LASTEXITCODE -ne 0) { throw 'Echec flutter create' }
flutter pub get
if ($LASTEXITCODE -ne 0) { throw 'Echec flutter pub get' }
Write-Host 'Projet prepare. Executer scripts\verifier_windows.ps1'
